#[test]fn flight_pause_vehicle_and_setback(){use no_clip::*;let mut m=NoClip::default();let speed=f64::from(m.speed);assert_eq!(m.tick(true,false,false,1,true,true,[0.0,1.0]),Tick::Apply{vehicle:false,velocity:Some([-0.0,speed,speed])});m.only_in_vehicle=true;assert_eq!(m.tick(true,false,false,0,false,false,[0.0,1.0]),Tick::Clear);assert!(!m.setback(true,false));assert!(m.setback(true,true));assert_eq!(m.tick(true,true,true,0,false,false,[0.0,1.0]),Tick::Apply{vehicle:true,velocity:None});m.on_disabled();assert!(!m.no_clip_set);}
#[test]fn cancelled_original_flags_record_without_actor_work(){use packets::*;use mod_api::ClientboundPlayPacket;let service=no_clip_packets::NoClipPackets::default();let mut position=ClientboundPlayPacket::PlayerPosition(());let mut event=PacketEvent{context:Context(true),packet:&mut position,cancelled:true};service.incoming(&mut event);assert_eq!(service.take_pending(),0);service.set_running(true);service.incoming(&mut event);assert_eq!(service.take_pending(),1);assert!(event.cancelled);event.context=Context(false);service.incoming(&mut event);assert_eq!(service.take_pending(),0);}
